page=(p/'audit-batch-01.html').read_text();start=page.index('<tbody>');end=page.index('</tbody>',start);rows=''.join('<tr><td dir="ltr">'+html.escape(r['id'])+'</td><td>'+html.escape(r['category'])+'</td><td>'+html.escape(r['answerText'])+'</td><td>'+html.escape('؛ '.join(r['findings']) or 'المفتاح سليم؛ توضيح الشرح ومراجعة الصعوبة.')+'</td></tr>' for r in records);page=page[:start+7]+rows+page[end:];intro_start=page.index('<h1>');table_start=page.index('<section><h2>سجل');page=page[:intro_start]+f'<h1>مراجعة الدفعة الثانية — الأسئلة 101–200</h1><p>1 أكتوبر 2026 · 75 لفظي و25 كمي · ترتيب السجلات في البنك.</p><section><h2>نتيجة المراجعة</h2><p>راجعت الإجابات والنصوص والخيارات والشروح في الأسئلة المئة. وجدت ملاحظات محددة في {len(issues)} سؤالًا، شملت غموض العلاقات، وتعدد الإجابات المحتملة، وأخطاء الإشارة إلى ترتيب الخيارات، وافتراضات مسائل العمال والخلط.</p><p>صححت سؤال فهم مقروء كانت عدة خيارات فيه تحقق نص السؤال المنفي. بقيت مفاتيح الإجابة في مواضعها بعد تحسين النصوص والخيارات. الحسابات في الأسئلة الكمية الخمسة والعشرين سليمة؛ أعيدت كتابة الشروح المئة.</p><p>الإجمالي المراجع 200 من 1000؛ المتبقي 800. الدفعة الأولى وبقية الأسئلة خارج هذه الدفعة لم تُغيّر. النتائج السابقة تحتفظ بنصوصها ومفاتيحها كما كانت.</p><p>هذه مراجعة تحريرية ومنطقية، وليست اعتمادًا رسميًا أو معايرة سيكومترية. الصعوبة تقدير يحتاج نتائج استخدام فعلية.</p><p><a href="audit-batch-01.html">تقرير الدفعة الأولى</a></p><button onclick="window.print()">طباعة / حفظ PDF</button></section>'+page[table_start:];page=page.replace('مراجعة أول 100 سؤال | قدرات','مراجعة الأسئلة 101–200 | قدرات');(p/'audit-batch-02.html').write_text(page)
